cases.setup_script:
! /usr/bin/getent passwd 4242 >/dev/null || { echo "CONTROL-FAILED uid 4242 has a passwd entry"; exit 98; }
[[ $(/usr/bin/unshare --user --map-user=4242 --map-group=4242 /usr/bin/id -u) == 4242 ]] || { echo "CONTROL-FAILED userns map"; exit 98; }
/usr/bin/unshare --user --map-user=4242 --map-group=4242 /usr/bin/sh -c '/usr/bin/getent passwd 4242 >/dev/null; [ "$?" -eq 2 ]' || { echo "CONTROL-FAILED namespace NSS lookup"; exit 98; }
